close
clear all

x = linspace(-2,2,20);
y = linspace(-2,2,20);
[X, Y] = meshgrid(x, y);

f = sin((X.^2 + Y.^2) / 20) .* exp(-(X.^2 + Y.^2));

figure(1); %[output:3e540829]
h = surf(X, Y, f); %[output:3e540829]
shading interp; %[output:3e540829]
colorbar; %[output:3e540829]
title('Trimatis turio grafikas'); %[output:3e540829]
xlabel('x'); ylabel('y'); zlabel('f(x,y)'); %[output:3e540829]
rotate(h, [0 0 1], 65) %[output:3e540829]
%%
close
clear all

x1 = linspace(-2,2,20);
y1 = linspace(-2,2,20);
[X1, Y1] = meshgrid(x1, y1);

f1 = sin((abs(X1+Y1))/20) .* exp(abs(-(X1+Y1)));

figure(2); %[output:0221b73d]
h1 = surf(X1, Y1, f1); %[output:0221b73d]
shading interp; %[output:0221b73d]
colorbar; %[output:0221b73d]
title('Trimatis pavirsiaus grafikas'); %[output:0221b73d]
xlabel('x'); ylabel('y'); zlabel('f(x,y)'); %[output:0221b73d]
rotate(h1, [0 0 1], 60); %[output:0221b73d]
%%
close all
clear

x2 = linspace(-2,2,20);
y2 = linspace(-2,2,20);
[X2, Y2] = meshgrid(x2, y2);

z = 1-(X2.^2+Y2.^2);

figure(3); %[output:1658cab0]
surf(X2, Y2, z); %[output:1658cab0]
shading interp; %[output:1658cab0]
colorbar; %[output:1658cab0]
title('interp shading tipo grafikas'); %[output:1658cab0]

figure(4); %[output:7b0ad536]
surf(X2, Y2, z); %[output:7b0ad536]
shading flat; %[output:7b0ad536]
colorbar; %[output:7b0ad536]
title('flat shading tipo grafikas'); %[output:7b0ad536]

figure(5); %[output:7bc9adda]
surf(X2, Y2, z); %[output:7bc9adda]
shading faceted; %[output:7bc9adda]
colorbar; %[output:7bc9adda]
title('faceted shading tipo grafikas'); %[output:7bc9adda]

